<?php
require __DIR__.'/../config/app.php';require_role('admin');ensure_event_application_schema();
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$id=(int)($_POST['id']??0);$action=(string)($_POST['action']??'status');
    try{$pdo=db();$q=$pdo->prepare('SELECT a.user_id,e.title FROM event_applications a JOIN events e ON e.id=a.event_id WHERE a.id=?');$q->execute([$id]);$application=$q->fetch();if(!$application){flash('Application not found.','error');}elseif($action==='delete'){$pdo->beginTransaction();$pdo->prepare('DELETE FROM event_applications WHERE id=?')->execute([$id]);$notify=$pdo->prepare('INSERT INTO notifications(user_id,title,message) SELECT ?,?,? WHERE COALESCE((SELECT in_app_notifications FROM user_settings WHERE user_id=?),1)=1');$notify->execute([$application['user_id'],'Event application removed',$application['title'].' application was removed by an administrator.',$application['user_id']]);$pdo->commit();flash($notify->rowCount()?'Application deleted and student notified.':'Application deleted. Student notifications are turned off.');}else{$status=(string)($_POST['status']??'');if(!in_array($status,['Pending','Shortlisted','Approved','Rejected','Waitlisted'],true)){flash('Choose a valid application status.','error');go('admin/applications.php');}$pdo->beginTransaction();$pdo->prepare('UPDATE event_applications SET status=? WHERE id=?')->execute([$status,$id]);$notify=$pdo->prepare('INSERT INTO notifications(user_id,title,message) SELECT ?,?,? WHERE COALESCE((SELECT in_app_notifications FROM user_settings WHERE user_id=?),1)=1');$notify->execute([$application['user_id'],'Application status updated',$application['title'].' application status is now '.$status.'.',$application['user_id']]);$pdo->commit();flash($notify->rowCount()?'Application status updated and student notified.':'Application status updated. Student notifications are turned off.');}}
    catch(Throwable $t){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();flash($action==='delete'?'Could not delete the application.':'Could not update the application.','error');}
    go('admin/applications.php');
}
$search=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'');$rows=[];
try{$sql='SELECT a.id,a.status,a.applied_at,e.title,e.category,u.name,u.email,d.applicant_name,d.gr_no,d.mobile_number,d.department,d.semester,d.application_role FROM event_applications a JOIN events e ON e.id=a.event_id JOIN users u ON u.id=a.user_id LEFT JOIN event_application_details d ON d.application_id=a.id WHERE 1=1';$params=[];if($search!==''){$sql.=' AND (u.name LIKE ? OR u.email LIKE ? OR e.title LIKE ? OR d.gr_no LIKE ?)';$term='%'.$search.'%';array_push($params,$term,$term,$term,$term);}if(in_array($statusFilter,['Pending','Shortlisted','Approved','Rejected','Waitlisted'],true)){$sql.=' AND a.status=?';$params[]=$statusFilter;}$sql.=' ORDER BY a.applied_at DESC';$q=db()->prepare($sql);$q->execute($params);$rows=$q->fetchAll();}catch(Throwable $t){$rows=[];}
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="eventhub-applications-'.date('Ymd').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Student','Email','Event','Category','Applied','GR No','Mobile','Department','Semester','Role','Status']);foreach($rows as $r)fputcsv($out,[$r['applicant_name']??$r['name'],$r['email'],$r['title'],$r['category'],$r['applied_at'],$r['gr_no'],$r['mobile_number'],$r['department'],$r['semester'],$r['application_role'],$r['status']]);fclose($out);exit;}
$perPage=25;$totalRecords=count($rows);$totalPages=(int)ceil($totalRecords/$perPage);$currentPage=max(1,min($totalPages?:1,(int)($_GET['page']??1)));$rows=array_slice($rows,($currentPage-1)*$perPage,$perPage);$pageTitle='Event Applications';$bodyClass='dashboard-page admin-page';$activePage='applications';require __DIR__.'/../includes/header.php';
?><div class="dash-layout admin-layout"><?php require __DIR__.'/../includes/sidebar.php';?><main class="content-page admin-content admin-events-page"><header class="admin-page-heading"><div><span class="admin-eyebrow">EVENT MANAGEMENT</span><h1>Event Applications</h1><p>Review student applications and update their status.</p></div></header><?php require __DIR__.'/event-nav.php';?><section class="admin-work-card"><form method="get" class="admin-report-filters"><input name="q" value="<?=e($search)?>" placeholder="Student, event, GR No."><select name="status"><option value="">All statuses</option><?php foreach(['Pending','Shortlisted','Approved','Rejected','Waitlisted'] as $s):?><option value="<?=$s?>" <?=$statusFilter===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn primary">Search</button><a class="btn outline" href="<?=url('admin/applications.php?'.http_build_query(['q'=>$search,'status'=>$statusFilter,'export'=>'csv']))?>">Export CSV</a></form></section><section class="admin-work-card"><div class="admin-card-heading"><span class="admin-heading-icon"><?=eventhub_icon('clipboard')?></span><div><h2>Recent applications <span class="admin-count"><?=count($rows)?></span></h2><p>Application updates respect each student’s in-app notification preference.</p></div></div><?php if($rows):?><div class="table-wrap admin-table-wrap"><table><thead><tr><th>Student</th><th>Event</th><th>Category</th><th>Applied on</th><th>Student details</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><span class="pill <?=e($r['category'])?>"><?=e(ucfirst($r['category']))?></span></td><td><?=date('d M Y',strtotime($r['applied_at']))?></td><td><?=e($r['applicant_name']??$r['name'])?><small>GR No.: <?=e($r['gr_no']??'—')?> · <?=e($r['mobile_number']??'—')?></small><small><?=e($r['department']??'—')?> · Semester <?=e(isset($r['semester'])?(string)$r['semester']:'—')?> · <?=e($r['application_role']??'—')?></small></td><td><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="application-status" name="status" onchange="this.form.submit()" aria-label="Application status for <?=e($r['name'])?>"><?php foreach(['Pending','Shortlisted','Approved','Rejected','Waitlisted'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td><td><form method="post" class="inline-form" onsubmit="return confirm('Delete this student application? This cannot be undone.')"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button type="submit" class="text-button danger-text">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">New student applications will appear here.</div><?php endif;?></section><?php require __DIR__.'/../includes/admin-pagination.php';?></main></div><?php require __DIR__.'/../includes/footer.php';
